'use client'

import * as React from 'react'

import { useOffscreen } from './use-reduced-motion'
import './halftone.css'

export type HalftoneProps = React.ComponentPropsWithoutRef<'div'> & {
    color?: string
    /** Dot spacing in px. */
    spacing?: number
    /** Seconds for the dense band to travel across. */
    speed?: number
    paused?: boolean
}

// Print-style halftone dots, with a band of larger dots sweeping across.
const Halftone = ({ color = 'rgba(244, 114, 182, 0.55)', spacing = 14, speed = 8, paused = false, className, style, children, ...props }: HalftoneProps) => {
    const ref = React.useRef<HTMLDivElement | null>(null)
    const offscreen = useOffscreen(ref)

    return <div
        ref={ref}
        className={['rad-fx-halftone', className].filter(Boolean).join(' ')}
        data-state={paused || offscreen ? 'paused' : 'running'}
        style={{ '--rad-fx-halftone-color': color, '--rad-fx-halftone-spacing': `${spacing}px`, '--rad-fx-halftone-speed': `${speed}s`, ...style } as React.CSSProperties}
        {...props}
    >
        <div className="rad-fx-halftone-layer" aria-hidden="true">
            <span className="rad-fx-halftone-small" />
            <span className="rad-fx-halftone-large" />
        </div>
        <div className="rad-fx-halftone-content">{children}</div>
    </div>
}

export default Halftone

.rad-fx-halftone {
    position: relative;
    isolation: isolate;
    overflow: hidden;
}

.rad-fx-halftone-layer {
    position: absolute;
    inset: 0;
    z-index: -1;
    pointer-events: none;
}

.rad-fx-halftone-content { position: relative; }

.rad-fx-halftone[data-state='paused'] .rad-fx-halftone-layer,
.rad-fx-halftone[data-state='paused'] .rad-fx-halftone-layer * { animation-play-state: paused !important; }

.rad-fx-halftone-small,
.rad-fx-halftone-large {
    position: absolute;
    inset: 0;
    background-size: var(--rad-fx-halftone-spacing, 14px) var(--rad-fx-halftone-spacing, 14px);
}

.rad-fx-halftone-small {
    background-image: radial-gradient(circle, var(--rad-fx-halftone-color) 1px, transparent 1.5px);
    opacity: 0.45;
}

.rad-fx-halftone-large {
    background-image: radial-gradient(circle, var(--rad-fx-halftone-color) 3.2px, transparent 3.8px);
    mask-image: linear-gradient(100deg, transparent 20%, #000 45%, #000 55%, transparent 80%);
    mask-size: 220% 100%;
    animation: rad-fx-halftone var(--rad-fx-halftone-speed, 8s) ease-in-out infinite alternate;
}

@keyframes rad-fx-halftone {
    from { mask-position: 100% 0; }
    to { mask-position: 0% 0; }
}

@media (prefers-reduced-motion: reduce) {
    .rad-fx-halftone-large { animation: none; mask-position: 50% 0; }
}

[data-rad-fx-motion='reduce'] .rad-fx-halftone-large { animation: none; mask-position: 50% 0; }
